// Per-object memo: freed automatically when the req object is gone
const parsedCookies = new WeakMap();

function cookies(req) {
  let c = parsedCookies.get(req);
  if (!c) {
    c = parse(req.headers.cookie);
    parsedCookies.set(req, c);
  }
  return c;
}

