const { Worker } = require('node:worker_threads');

const workerCode = `
  const { parentPort, workerData } = require('node:worker_threads');
  let sum = 0;
  for (let i = 1; i <= workerData.n; i++) sum += i;
  parentPort.postMessage(sum);
`;

function runInWorker(n) {
  return new Promise((resolve, reject) => {
    const w = new Worker(workerCode, { eval: true, workerData: { n } });
    w.once('message', resolve);
    w.once('error', reject);
  });
}

console.log('start heavy job');
runInWorker(1e7).then((sum) => console.log('sum =', sum));
setTimeout(() => console.log('main thread still free'), 0);

